function makeId(subject, title) {
  return `${subject}-${title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '')}`;
}

function subjectName(subject) {
  if (subject === 'language') return 'Language & Thinking';
  return subject === 'cs' ? 'Computer Science' : subject[0].toUpperCase() + subject.slice(1);
}

function buildLearning(subject, stage, title, level, bigIdea, mentalModel, guidedExample, bridge, predictionQuestion, predictionAnswer, quizQuestion, correctAnswer, misconception) {
  const name = subjectName(subject);

  return {
    intuition: {
      plainEnglish: bigIdea,
      concept: mentalModel,
    },
    formalIdea: {
      definition: `${title} is the ${level.toLowerCase()} concept in ${name} for this stage: ${stage}.`,
      terminology: `Key terms: ${title.toLowerCase()}, input, output, relationship, model, assumption, and evidence.`,
    },
    derivation: [
      `Start with the situation: ${bigIdea}`,
      `Name the quantities or parts that matter. In this lesson, the useful mental model is: ${mentalModel}`,
      `Apply the rule carefully rather than guessing. The core working example is: ${guidedExample}`,
      `Check the result against the concept. A good answer should agree with this idea: ${correctAnswer}.`,
    ],
    workedExamples: [
      {
        title: 'Direct application',
        inputs: predictionQuestion,
        steps: [
          'Identify what the problem is asking before calculating.',
          `Use the lesson idea: ${bigIdea}`,
          `Reason through the expected behavior: ${predictionAnswer}`,
        ],
        output: predictionAnswer,
      },
      {
        title: 'Connected application',
        inputs: bridge,
        steps: [
          'Translate the concept into a related subject.',
          'Name the shared structure: inputs, changes, constraints, or outputs.',
          `Use that structure to explain why the connection works: ${bridge}`,
        ],
        output: `The same idea can be used outside this lesson because ${bridge.toLowerCase()}`,
      },
    ],
    practiceProblems: [
      {
        difficulty: 'Easy',
        prompt: `State the main rule of ${title} in one sentence, then give one simple input-output example.`,
        solution: [
          `Main rule: ${bigIdea}`,
          `Example pattern: ${guidedExample}`,
          'The answer is strong if it names the input, the operation or relationship, and the output.',
        ],
      },
      {
        difficulty: 'Medium',
        prompt: quizQuestion,
        solution: [
          `Correct answer: ${correctAnswer}.`,
          `Reason: ${correctAnswer} matches the concept, while "${misconception}" is a common misunderstanding.`,
          'Check the answer by connecting it back to the formal idea, not by memorizing the wording.',
        ],
      },
      {
        difficulty: 'Challenge',
        prompt: `Use ${title} to explain a situation in another field: ${bridge}`,
        solution: [
          'First, identify the shared structure between the lesson and the connected field.',
          `Connection: ${bridge}`,
          'Then explain what changes, what stays constrained, and what evidence would show the idea is working.',
        ],
      },
    ],
    commonMistakes: [
      {
        mistake: misconception,
        whyWrong: `This misses the key relationship. The useful idea is: ${correctAnswer}.`,
      },
      {
        mistake: 'Using the right word but not checking the inputs, assumptions, or units.',
        whyWrong: 'Concepts become reliable only when they are tied to the quantities and conditions in the problem.',
      },
      {
        mistake: 'Treating the example as the only case instead of seeing the general pattern.',
        whyWrong: `The example is evidence for the broader idea: ${bigIdea}`,
      },
    ],
    connections: {
      math: name === 'Math' ? `This is a math idea directly: ${bigIdea}` : 'Math supplies the language for quantities, relationships, rates, and uncertainty.',
      physics: name === 'Physics' ? `This is a physics idea directly: ${bigIdea}` : 'Physics tests the idea against real motion, energy, force, measurement, or signals.',
      computerScience: name === 'Computer Science' ? `This is a computer science idea directly: ${bigIdea}` : 'Computer science turns the idea into procedures, simulations, data structures, or interfaces.',
      ai: 'AI systems use the same habit: define inputs, compare outputs with reality, measure error, and update a model.',
    },
    buildLink: `In labs, test the prediction before changing controls. In Build Mode, write pseudocode that turns "${title}" into inputs, steps, and an output. In real software, this becomes a small model, validator, simulator, or decision rule.`,
  };
}

function lesson(subject, stage, title, level, bigIdea, mentalModel, guidedExample, bridge, predictionQuestion, predictionAnswer, quizQuestion, correctAnswer, misconception) {
  return {
    id: makeId(subject, title),
    subject: subjectName(subject),
    stage,
    title,
    level,
    bigIdea,
    whyItMatters: `${bigIdea} This matters in real projects because ${bridge.toLowerCase()} AI systems also depend on this idea when they measure data, choose actions, or learn from examples.`,
    mentalModel,
    guidedExample,
    bridge,
    prediction: {
      question: predictionQuestion,
      answer: predictionAnswer,
    },
    quiz: {
      question: quizQuestion,
      options: [
        correctAnswer,
        misconception,
        'Memorize the words without checking the relationship',
        'Ignore the inputs and guess from the title',
      ],
      correctIndex: 0,
      feedback: [
        `Correct. ${correctAnswer} is the useful idea to carry forward.`,
        `Not quite. ${misconception} is a common trap, but it misses the structure of this lesson.`,
        'Not quite. Memorizing labels is weaker than reasoning from the relationship.',
        'Not quite. The inputs and constraints are what make the answer meaningful.',
      ],
    },
    learning: buildLearning(subject, stage, title, level, bigIdea, mentalModel, guidedExample, bridge, predictionQuestion, predictionAnswer, quizQuestion, correctAnswer, misconception),
  };
}

