const languageSpecs = [
  [languageStages.foundations, 'Nouns Name Things', 'Foundation', 'A noun names a person, place, thing, or idea.', 'A noun is a label for something your sentence is talking about.', 'In "The robot measured temperature," robot and temperature are nouns.', 'Clear nouns help math, physics, and code identify the objects and quantities in a problem.', 'In "The sensor recorded motion," which words are nouns?', 'Sensor and motion are nouns because they name things or ideas.', 'What does a noun do?', 'Names a person, place, thing, or idea', 'Shows how fast an action happens'],
  [languageStages.foundations, 'Verbs Show Action or State', 'Foundation', 'A verb tells what happens or what something is.', 'A verb is the engine of a sentence.', 'In "The model predicts a value," predicts is the verb.', 'Physics problems depend on verbs like moves, accelerates, collides, and balances.', 'In "The force changes motion," which word is the verb?', 'Changes is the verb because it tells what force does.', 'What does a verb usually show?', 'Action, change, or state of being', 'Only the name of an object'],
  [languageStages.foundations, 'Adjectives Add Specific Detail', 'Foundation', 'An adjective describes a noun so the reader knows which kind, how many, or what quality.', 'An adjective is a zoom lens for a noun.', 'In "a rough surface," rough tells what kind of surface.', 'Precise adjectives make observations and bug reports easier to trust.', 'Why is "the red wire" clearer than "the wire"?', 'Red narrows which wire you mean.', 'What does an adjective modify?', 'A noun', 'A whole algorithm every time'],
  [languageStages.foundations, 'Adverbs Describe Actions', 'Foundation', 'An adverb describes a verb, adjective, or another adverb.', 'An adverb tells how, when, where, or how much.', 'In "the graph rises quickly," quickly describes rises.', 'Rates, trends, and careful instructions often depend on adverb-like precision.', 'In "increase slowly," what does slowly explain?', 'How the increase happens.', 'What question can an adverb answer?', 'How, when, where, or how much', 'Which noun is being named'],
  [languageStages.foundations, 'Sentence Structure', 'Foundation', 'A complete sentence usually has a subject and a predicate.', 'A sentence is a tiny thought with someone or something doing or being something.', 'In "The loop repeats," the loop is the subject and repeats is the predicate.', 'Good sentences make problem statements easier to solve and code comments easier to follow.', 'What is missing in "Because the value changed"?', 'It is incomplete because the thought is not finished.', 'What does a complete sentence express?', 'A complete thought', 'A list with no relationship'],
  [languageStages.foundations, 'Punctuation Controls Meaning', 'Foundation', 'Punctuation shows stops, joins, emphasis, and relationships between ideas.', 'Punctuation is traffic control for reading.', 'A comma can separate steps: measure, record, compare.', 'Punctuation prevents ambiguity in lab notes, equations explained in words, and instructions.', 'Why does "Let us eat, Kai" differ from "Let us eat Kai"?', 'The comma changes who is being addressed.', 'What does punctuation help control?', 'How ideas are grouped and read', 'The mass of an object'],
  [languageStages.foundations, 'Grammar Basics as Rules for Meaning', 'Foundation', 'Grammar is the system that makes words work together clearly.', 'Grammar is the wiring behind a sentence.', 'Subject-verb agreement makes "the results are" different from "the result is."', 'Clear grammar reduces errors when writing instructions, proofs, and bug reports.', 'Why should subject and verb agree?', 'So the sentence accurately matches one thing or many things.', 'What is grammar for?', 'Making word relationships clear', 'Making writing sound complicated'],
  [languageStages.intermediate, 'Writing Clear Sentences', 'Core', 'A clear sentence puts the main idea where the reader can find it.', 'Clarity means the reader does not have to guess the point.', 'Instead of "Due to it, this changed," write "Gravity changed the ball velocity."', 'Clear sentences are the foundation of clear reasoning and precise code documentation.', 'Which sentence is clearer: "It did it" or "The loop updated the score"?', 'The loop updated the score names the actor and action.', 'What makes a sentence clear?', 'A specific actor, action, and object or idea', 'Extra words that hide the point'],
  [languageStages.intermediate, 'Structuring Paragraphs', 'Core', 'A paragraph develops one main idea with supporting details.', 'A paragraph is a small container for one piece of thinking.', 'Start with a claim, add evidence, then explain why the evidence matters.', 'Proofs, lab reports, and design notes all need organized paragraphs.', 'What should one paragraph usually focus on?', 'One main idea', 'Every topic at once'],
  [languageStages.intermediate, 'Logical Flow', 'Core', 'Logical flow means each sentence follows from the previous one.', 'Flow is a path the reader can walk without jumping gaps.', 'Define the variable, show the equation, then solve it.', 'Algorithms and physics derivations both depend on ordered reasoning.', 'Why define terms before using them?', 'So the reader can follow later steps.', 'What is logical flow?', 'An ordered path from one idea to the next', 'A collection of disconnected facts'],
  [languageStages.intermediate, 'Avoiding Ambiguity', 'Core', 'Ambiguity happens when a sentence can mean more than one thing.', 'An ambiguous sentence is a fork with no sign.', 'The sentence "measure the box with the sensor" could mean the box has the sensor or the sensor does the measuring.', 'Ambiguity causes bugs, bad requirements, and confused science instructions.', 'How can you fix "it changed after it moved"?', 'Name the objects: "Velocity changed after the cart moved down the ramp."', 'What is ambiguity?', 'More than one possible meaning', 'A sentence with too many correct details'],
  [languageStages.intermediate, 'Definitions and Examples', 'Core', 'A strong explanation defines the idea and then gives an example.', 'Definition gives the rule; example makes it visible.', 'Define acceleration as velocity change over time, then show 0 to 10 m/s in 2 s.', 'Teaching AI, math, physics, or code requires both precision and examples.', 'Why pair a definition with an example?', 'The definition is precise and the example makes it concrete.', 'What does a good example do?', 'Shows the idea in a concrete case', 'Replaces the need for accuracy'],
  [languageStages.intermediate, 'Transitions and Signposts', 'Core', 'Transitions show how ideas relate: cause, contrast, sequence, or conclusion.', 'A transition is a road sign for thinking.', 'Words like therefore, however, first, and because tell the reader how to connect ideas.', 'Good transitions make proofs, essays, and technical docs easier to follow.', 'What does "therefore" usually signal?', 'A conclusion from earlier ideas.', 'What is a transition for?', 'Showing the relationship between ideas', 'Adding decoration only'],
  [languageStages.intermediate, 'Evidence and Claims', 'Core', 'A claim says what you think; evidence shows why someone should believe it.', 'A claim is the answer, evidence is the support beam.', 'Claim: the algorithm is slower. Evidence: runtime doubled when input size doubled.', 'Science, debugging, and critical thinking all require evidence-backed claims.', 'Why is "it feels faster" weak evidence?', 'It is subjective and not measured.', 'What should support a claim?', 'Evidence that can be checked', 'A louder voice'],
  [languageStages.advanced, 'Argument Structure', 'Advanced', 'An argument connects premises to a conclusion.', 'An argument is a bridge from reasons to a claim.', 'Premise: all tests passed. Premise: tests cover edge cases. Conclusion: the change is probably safe.', 'Algorithms, proofs, and scientific explanations all use argument structure.', 'What is a premise?', 'A reason used to support a conclusion', 'A random ending sentence'],
  [languageStages.advanced, 'Persuasion with Integrity', 'Advanced', 'Good persuasion helps people see reasons clearly without hiding weaknesses.', 'Persuasion is guiding attention honestly.', 'A fair proposal states benefits, costs, evidence, and uncertainty.', 'Responsible AI and science communication depend on honest persuasion.', 'Why mention uncertainty in a persuasive argument?', 'It builds trust and prevents overclaiming.', 'What is ethical persuasion?', 'Using clear reasons without misleading people', 'Winning by hiding evidence'],
  [languageStages.advanced, 'Clarity of Thought', 'Advanced', 'Clear writing often reveals clear thinking because it forces ideas into testable shape.', 'If you cannot say the idea clearly, you may not fully understand it yet.', 'Rewrite "stuff affects things" as "friction reduces the cart acceleration."', 'Precise thinking improves problem solving in every subject.', 'What should you do when a sentence feels vague?', 'Name the specific actor, action, and result.', 'How does clear writing help thinking?', 'It exposes the exact idea and gaps', 'It hides uncertainty better'],
  [languageStages.advanced, 'Precise Communication', 'Advanced', 'Precise communication chooses words that match the exact relationship.', 'Precision is using the right-sized tool.', 'Say "correlates with" when you do not have evidence for "causes."', 'Precision prevents false claims in data, science, AI, and debate.', 'Why not say "causes" when you only measured correlation?', 'Because correlation alone does not prove cause.', 'What does precision protect?', 'Meaning and truthfulness', 'Longer sentences automatically'],
  [languageStages.advanced, 'Explaining Complex Ideas Simply', 'Advanced', 'A simple explanation keeps the core structure while removing unnecessary load.', 'Simplicity is not dumbing down; it is choosing the right ladder.', 'Explain a neural network as layers of adjustable functions before naming all the math.', 'Great teachers, engineers, and AI tools make complex systems understandable.', 'What should a simple explanation keep?', 'The core relationship that makes the idea work', 'Every technical detail at once'],
  [languageStages.advanced, 'Critical Reading', 'Advanced', 'Critical reading checks claims, evidence, assumptions, and missing alternatives.', 'Read like a scientist: curious, fair, and hard to fool.', 'When a graph claims improvement, inspect axes, sample size, and comparison group.', 'AI outputs, news, documentation, and research papers all require critical reading.', 'What should you inspect before trusting a graph?', 'Axes, labels, scale, data source, and comparison.', 'What is critical reading?', 'Checking claims and evidence carefully', 'Rejecting everything immediately'],
];

function buildSubject(title, specs, subjectKey) {
  return {
    title,
    lessons: specs.map((spec) => lesson(subjectKey, ...spec)),
  };
}

export const deepLessons = {
  math: buildSubject('Math', mathSpecs, 'math'),
  physics: buildSubject('Physics', physicsSpecs, 'physics'),
  cs: buildSubject('Computer Science', csSpecs, 'cs'),
  language: buildSubject('Language & Thinking', languageSpecs, 'language'),
};
